<header class="admin-page-head compact-head">
    <div><p class="admin-eyebrow">Taxonomy / collection chapters</p><h1>Categories <span class="head-count"><?= e(count($categories)) ?></span></h1><p class="admin-lede">Keep the archive easy to browse, understand and quote.</p></div>
    <?php if ($admin_repository->isReady()): ?><a class="admin-primary-button" href="<?= e(admin_url('/categories/new')) ?>">Add category <span aria-hidden="true">↗</span></a><?php endif; ?>
