<?php if (!empty($admin_error)): ?><div class="admin-state-card <?= e($admin_repository->status()) ?>"><span class="state-dot"></span><div><strong>Taxonomy status</strong><p><?= e($admin_error) ?></p></div></div><?php endif; ?>
<?php if (!empty($errors)): ?><div class="admin-alert error" role="alert"><ul><?php foreach ($errors as $error): ?><li><?= e($error) ?></li><?php endforeach; ?></ul></div><?php endif; ?>
<?php if (!empty($form) || $editing !== null): ?><section class="admin-panel category-editor"><div class="panel-heading"><div><p class="admin-eyebrow"><?= $editing !== null ? 'Edit chapter' : 'New chapter' ?></p><h2><?= $editing !== null ? 'Tune the category.' : 'Start a new chapter.' ?></h2></div><a class="panel-link" href="<?= e(admin_url('/categories')) ?>">Close ↗</a></div><form class="admin-editor-form" method="post" action="<?= e($editing !== null ? admin_url('/categories/edit/' . (int) $form['id']) : admin_url('/categories/new')) ?>"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="id" value="<?= e($form['id'] ?? 0) ?>"><div class="form-grid"><label><span>Name <b>*</b></span><input name="name" value="<?= e($form['name'] ?? '') ?>" maxlength="191" required></label><label><span>Slug <b>*</b></span><input name="slug" value="<?= e($form['slug'] ?? '') ?>" maxlength="120" pattern="[a-z0-9-]+" required></label><label><span>Parent slug</span><input name="parent_slug" value="<?= e($form['parent_slug'] ?? '') ?>" maxlength="191" placeholder="Optional"></label><label class="span-2"><span>Description</span><textarea name="description" rows="4" maxlength="5000"><?= e($form['description'] ?? '') ?></textarea></label></div><div class="editor-submit"><a class="admin-cancel-link" href="<?= e(admin_url('/categories')) ?>">Cancel</a><button class="admin-primary-button" type="submit"><?= $editing !== null ? 'Save category' : 'Create category' ?> <span>↗</span></button></div></form></section><?php endif; ?>
<section class="admin-panel admin-table-panel"><div class="table-toolbar"><form class="admin-search" method="get" action="<?= e(admin_url('/categories')) ?>"><label class="sr-only" for="category-search">Search categories</label><input id="category-search" type="search" name="q" value="<?= e($query) ?>" placeholder="Search category or slug"><button type="submit">Search ↗</button></form><span class="toolbar-meta"><?= e(count($categories)) ?> chapters</span></div><?php if (empty($categories)): ?><div class="empty-state table-empty"><span>◇</span><strong>No categories found</strong><p>Try another search or create a new collection chapter.</p></div><?php else: ?><div class="admin-table-scroll"><table class="admin-table"><thead><tr><th>Category</th><th>Slug</th><th>Parent</th><th>Products</th><th>Updated</th><th><span class="sr-only">Actions</span></th></tr></thead><tbody><?php foreach ($categories as $category): ?><tr><td><div class="table-primary"><a href="<?= e(admin_url('/categories/edit/' . (int) $category['id'])) ?>"><?= e($category['name']) ?></a><small><?= e($category['description'] ?: 'No description yet') ?></small></div></td><td class="mono-cell"><?= e($category['slug']) ?></td><td><?= e($category['parent_slug'] ?: '—') ?></td><td><span class="count-badge"><?= e($category['product_count']) ?></span></td><td><?= e($category['updated_at'] ? date('d M Y', strtotime($category['updated_at'])) : '—') ?></td><td><div class="table-actions"><a class="icon-action" href="<?= e(admin_url('/categories/edit/' . (int) $category['id'])) ?>">Edit</a><form method="post" action="<?= e(admin_url('/categories')) ?>" data-confirm="Delete this empty category?"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="admin_action" value="delete_category"><input type="hidden" name="id" value="<?= e($category['id']) ?>"><button class="icon-action danger" type="submit" <?= (int) $category['product_count'] > 0 ? 'disabled title="Move assigned products first"' : '' ?>>Delete</button></form></div></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section>
